  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    names = [s['name'] for s in segments]
    importances = [s['importance'] for s in segments]
    minima = [s['minimum'] for s in segments]
    capacities = [s['capacity'] for s in segments]
    total_min = sum(minima)
    total_max = sum(capacities)
    if budget < total_min or budget > total_max:
        raise ValueError('Budget out of feasible range')
    allocations = list(minima)
    total_alloc = total_min
    while total_alloc < budget:
        best_idx = -1
        best_ratio = -1.0
        for i in range(n):
            if allocations[i] >= capacities[i]:
                continue
            ratio = importances[i] / (allocations[i] + 1)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx == -1:
            raise ValueError('Cannot allocate remaining budget (all segments at capacity)')
        allocations[best_idx] += 1
        total_alloc += 1
    by_name = {names[i]: allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': total_alloc}
